import {drawDomain} from './domain-visuals.js';
import {drawRL} from './rl-visuals.js';
import {activate,conv,pool,normalize,softmax,chain,optimize,polynomialFit,trainData,mean} from './math.js';
export const colors={cyan:'#6bd5d4',lime:'#c5f66a',orange:'#f4b880',purple:'#b9a1e8',pink:'#eab2c7',muted:'#6d8374',grid:'#2b3c2e'};
const f=x=>Number.isFinite(x)?(Math.abs(x)<0.005?0:Number(x)).toFixed(2):'溢出';
export function setupCanvas(canvas){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(!r.width||!r.height)return null;if(canvas.width!==Math.round(r.width*d)||canvas.height!==Math.round(r.height*d)){canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d)}const g=canvas.getContext('2d');g.setTransform(canvas.width/500,0,0,canvas.height/240,0,0);g.clearRect(0,0,500,240);return g}
function text(g,s,x,y,c=colors.muted,size=17,align='center'){g.fillStyle=c;g.font=`${size}px "DM Sans","Noto Sans SC",sans-serif`;g.textAlign=align;g.fillText(s,x,y)}
function line(g,x,y,X,Y,c=colors.muted,width=2){g.beginPath();g.moveTo(x,y);g.lineTo(X,Y);g.strokeStyle=c;g.lineWidth=width;g.stroke()}
function dot(g,x,y,r=7,c=colors.lime,glow=false){g.beginPath();g.arc(x,y,r,0,Math.PI*2);g.fillStyle=c;if(glow){g.shadowColor=c;g.shadowBlur=14}g.fill();g.shadowBlur=0}
function ring(g,x,y,r,c=colors.lime){g.beginPath();g.arc(x,y,r,0,Math.PI*2);g.fillStyle='#19271d';g.fill();g.strokeStyle=c;g.lineWidth=2;g.stroke()}
function signal(g,a,b,t,c){line(g,...a,...b,c+'66',1.5);const p=((t%1)+1)%1;dot(g,a[0]+(b[0]-a[0])*p,a[1]+(b[1]-a[1])*p,4,c,true)}
function box(g,x,y,w,h,c=colors.lime,fill='#263629'){g.fillStyle=fill;g.fillRect(x,y,w,h);g.strokeStyle=c;g.lineWidth=1.5;g.strokeRect(x,y,w,h)}
function path(g,points,c=colors.lime,width=2.5,dash=[]){g.beginPath();points.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.strokeStyle=c;g.lineWidth=width;g.setLineDash(dash);g.stroke();g.setLineDash([])}
function axes(g,x=45,y=205,w=405,h=175){line(g,x,y,x+w,y,colors.grid);line(g,x,y,x,y-h,colors.grid)}
const chart=(g,fn,{xmin=-3,xmax=3,ymin=-1,ymax=4,c=colors.lime,dash=[]}={})=>{const points=Array.from({length:120},(_,i)=>{const x=xmin+(xmax-xmin)*i/119;return [45+(x-xmin)/(xmax-xmin)*405,205-(Math.max(ymin-.3,Math.min(ymax+.3,fn(x)))-ymin)/(ymax-ymin)*175]});path(g,points,c,2.5,dash)};
function matrix(g,a,x,y,s,{highlight=[],accent=colors.cyan,labels=true}={}){a.forEach((row,r)=>row.forEach((v,c)=>{const on=highlight.some(([i,j])=>i===r&&j===c),alpha=.12+Math.min(Math.abs(v)/9,.8);box(g,x+c*s,y+r*s,s-3,s-3,on?colors.lime:accent+'44',on?'#60733c':(v<0?colors.pink:accent)+Math.round(alpha*255).toString(16).padStart(2,'0'));if(labels)text(g,Math.abs(v)<1&&v!==0?f(v):v,x+c*s+(s-3)/2,y+r*s+s*.61,on?'#eff6dc':'#c9dfcf',Math.min(18,s*.36))}))}
const inputImage=[[0,0,8,0,0],[0,0,8,0,0],[0,0,8,0,0],[0,0,8,0,0],[0,0,8,0,0]];
const poolImage=[[1,3,2,4],[2,4,1,3],[5,2,8,1],[3,6,2,7]];
let fitCache=new Map();function fit(d,l){const k=d+':'+l;if(!fitCache.has(k)){if(fitCache.size>100)fitCache.clear();fitCache.set(k,polynomialFit(d,l))}return fitCache.get(k)}
export function hero(canvas,t){const g=setupCanvas(canvas);if(!g)return;const layers=[[55,[77,163]],[180,[30,90,150,210]],[320,[54,120,186]],[444,[120]]];for(let l=0;l<layers.length-1;l++)for(const [i,y]of layers[l][1].entries())for(const [j,Y]of layers[l+1][1].entries()){const c=l===2?colors.lime:colors.cyan;signal(g,[layers[l][0],y],[layers[l+1][0],Y],t*.4-l*.22+(i+j)*.12,c)}layers.forEach(([x,ys],l)=>ys.forEach(y=>{ring(g,x,y,l===3?15:10,l===3?colors.lime:colors.cyan);dot(g,x,y,3,l===3?colors.lime:colors.cyan)}))}
export function draw(canvas,id,p={},t=0,mini=false,state={}){const g=setupCanvas(canvas);if(!g)return '';if(id>28)return drawDomain(g,id,p,t,mini);if(id>20)return drawRL(g,id,p,t,mini,state);const C=colors;let out='';
switch(id){
case 1:{const w=p.w??.7,v=p.v??.4,b=p.b??0,z=w+2*v+b,y=Math.max(0,z);signal(g,[65,65],[247,120],t*.6,C.cyan);signal(g,[65,175],[247,120],t*.6+.2,C.purple);signal(g,[247,120],[435,120],t*.6-.4,C.lime);ring(g,247,120,35);text(g,'Σ',247,130,C.lime,29);dot(g,65,65,10,C.cyan,true);dot(g,65,175,10,C.purple,true);dot(g,435,120,11,C.lime,true);text(g,'x₁=1',65,35,C.cyan);text(g,'x₂=2',65,213,C.purple);text(g,f(w),152,66,C.cyan);text(g,f(v),152,184,C.purple);text(g,mini?'output':`y=${f(y)}`,432,165,C.lime);out=`z = ${f(w)} × 1 + ${f(v)} × 2 + ${f(b)} = ${f(z)}  →  ReLU = ${f(y)}`;break}
case 2:{const rows=p.rows??3,cols=p.cols??4,s=Math.min(38,175/rows,320/cols),x=250-cols*s/2,y=120-rows*s/2;matrix(g,Array.from({length:rows},(_,i)=>Array.from({length:cols},(_,j)=>i*cols+j+1)),x,y,s,{highlight:[[Math.floor(t)%rows,Math.floor(t*1.2)%cols]],accent:C.cyan});text(g,`[ ${rows} , ${cols} ]`,250,224,C.cyan,20);out=`形状 [${rows}, ${cols}] · ${rows*cols} 个数字 · 2 个维度`;break}
case 3:{const x=p.x??1.5,b=p.b??.2,h=[Math.max(0,x),Math.max(0,-x)],y=.8*h[0]+.3*h[1]+b;for(let i=0;i<2;i++){signal(g,[60,120],[245,60+120*i],t*.6,C.cyan);signal(g,[245,60+120*i],[430,120],t*.6-.5,C.lime);ring(g,245,60+120*i,23,C.cyan);text(g,f(h[i]),245,66+120*i,C.cyan,16)}ring(g,60,120,20,C.cyan);ring(g,430,120,25,C.lime);text(g,f(x),60,127,C.cyan);text(g,f(y),430,127,C.lime);text(g,'输入',60,217);text(g,'隐藏层 / ReLU',245,232);text(g,'输出',430,217);out=`h = [${f(h[0])}, ${f(h[1])}]  →  y = ${f(y)}`;break}
case 4:{const kind=p.kind??'ReLU',x=p.x??1;axes(g);chart(g,v=>activate(v,kind),{xmin:-4,xmax:4,ymin:-1.3,ymax:3.5,c:C.cyan});line(g,247,205,247,30,C.grid);const y=activate(x,kind);dot(g,45+(x+4)/8*405,205-(y+1.3)/4.8*175,7,C.lime,true);text(g,kind,110,44,C.cyan);out=`${kind}(${f(x)}) = ${f(y)}`;break}
case 5:{const pred=p.pred??5,kind=p.kind??'MSE',error=pred-3,L=kind==='MAE'?Math.abs(error):error**2;axes(g,45,205,405,150);const pos=v=>60+v/6*375;line(g,pos(3),130,pos(pred),70,C.pink,4);dot(g,pos(3),130,8,C.cyan,true);dot(g,pos(pred),70,8,C.pink,true);text(g,'目标 3',pos(3),169,C.cyan);text(g,`预测 ${f(pred)}`,pos(pred),42,C.pink);text(g,`${kind} = ${f(L)}`,250,228,C.lime,20);out=`误差 = ${f(error)}  ·  ${kind} 损失 = ${f(L)}`;break}
case 6:{const w=p.w??1,r=chain(w);const xs=[50,170,295,435],labels=['x=2',`h=${f(r.h)}`,`ŷ=${f(r.y)}`,'L'];for(let i=0;i<3;i++)signal(g,[xs[i+1]-23,100],[xs[i]+23,100],t*.6+i*.13,C.pink);xs.forEach((x,i)=>{ring(g,x,100,26,i?C.pink:C.cyan);text(g,i===3?f(r.L):i===0?'2':i===1?'h':'ŷ',x,107,i?C.pink:C.cyan,19);text(g,labels[i],x,157,C.muted,16)});text(g,`∂L/∂w = ${f(r.g)}`,250,216,C.pink,24);out=`预测 ${f(r.y)} · 损失 ${f(r.L)} · 梯度 ${f(r.g)} = 2 × (${f(r.y)}−3) × 0.5 × 2`;break}
case 7:{const lr=p.lr??.18,ps=optimize('SGD',lr,16),i=Math.floor(t*2)%ps.length;axes(g);chart(g,x=>x*x,{xmin:-4,xmax:4,ymin:0,ymax:16,c:C.lime});path(g,ps.slice(0,i+1).map(w=>[247.5+Math.max(-4,Math.min(4,w))*50.625,205-Math.min(16,w*w)/16*175]),C.cyan,1);const w=ps[i];dot(g,247.5+Math.max(-4,Math.min(4,w))*50.625,205-Math.min(16,w*w)/16*175,7,C.lime,true);text(g,'L(w) = w²',130,37,C.muted);text(g,`η = ${f(lr)}`,375,37,C.lime);out=`16 步后 w = ${f(ps.at(-1))} · L = ${f(ps.at(-1)**2)}${lr>=1?' · 轨迹超出画布时已截断显示':''}`;break}
case 8:{const lr=p.lr??.15;axes(g);['SGD','Momentum','Adam'].forEach((name,i)=>{const ps=optimize(name,lr),col=[C.cyan,C.orange,C.purple][i];path(g,ps.map((w,k)=>[50+k/24*385,200-Math.min(3.5,Math.abs(w))/3.5*155]),col,2.5);const n=Math.floor(t*3)%ps.length;dot(g,50+n/24*385,200-Math.min(3.5,Math.abs(ps[n]))/3.5*155,5,col,true);text(g,name,70+i*155,31,col,18)});text(g,'更新步数 →',380,232,C.muted,15);out=['SGD','Momentum','Adam'].map(name=>`${name}: |w₂₄|=${f(Math.abs(optimize(name,lr).at(-1)))}`).join('  ·  ');break}
case 9:{const ratio=p.ratio??60,valid=Math.floor((100-ratio)/2);for(let i=0;i<100;i++)dot(g,60+(i%20)*20,55+Math.floor(i/20)*29,5.5,i<ratio?C.cyan:i<ratio+valid?C.orange:C.purple);[[C.cyan,'训练',ratio],[C.orange,'验证',valid],[C.purple,'测试',100-ratio-valid]].forEach(([c,s,n],i)=>{dot(g,72+i*155,221,4,c);text(g,`${s} ${n}%`,132+i*145,226,c,16)});out=`训练 ${ratio} · 验证 ${valid} · 测试 ${100-ratio-valid}（共 100 个样本）`;break}
case 10:{const batch=p.batch??4,count=Math.ceil(24/batch),i=Math.floor(t)%count;for(let j=0;j<24;j++){const on=Math.floor(j/batch)===i;box(g,75+j%8*45,35+Math.floor(j/8)*44,30,30,on?C.lime:C.grid,on?'#617d35':'#26392c')}text(g,`batch ${i+1} / ${count}`,250,205,C.lime,23);out=`24 个样本 ÷ batch size ${batch} → 每 epoch ${count} 次更新`;break}
case 11:case 12:{const d=id===11?(p.degree??3):9,lambda=id===12?(p.lambda??.05):0,r=fit(d,lambda);axes(g);chart(g,x=>Math.sin(2.4*x),{xmin:-1,xmax:1,ymin:-1.6,ymax:1.6,c:C.muted,dash:[7,6]});chart(g,r.predict,{xmin:-1,xmax:1,ymin:-1.6,ymax:1.6,c:id===11?C.orange:C.lime});r.xs.forEach((x,i)=>dot(g,45+(x+1)/2*405,205-(r.ys[i]+1.6)/3.2*175,5,C.cyan));text(g,id===11?`degree = ${d}`:`λ = ${f(lambda)}`,125,25,id===11?C.orange:C.lime);out=`训练 MSE ${r.train.toFixed(4)}  ·  验证 MSE ${r.validation.toFixed(4)}`;break}
case 13:{const pos=p.pos??Math.floor(t)%9,row=Math.floor(pos/3),col=pos%3,k=p.kernel==='均值模糊'?Array.from({length:3},()=>[1/9,1/9,1/9]):[[-1,0,1],[-1,0,1],[-1,0,1]],outMat=Array.from({length:3},(_,r)=>Array.from({length:3},(_,c)=>Number(conv(inputImage,k,r,c).toFixed(1))));matrix(g,inputImage,28,25,35,{highlight:Array.from({length:9},(_,i)=>[row+Math.floor(i/3),col+i%3])});text(g,'→',270,125,C.orange,30);matrix(g,outMat,326,56,39,{accent:C.orange,highlight:[[row,col]]});text(g,'5 × 5 输入',110,225,C.cyan);text(g,'3 × 3 特征',385,225,C.orange);out=`窗口 [${row}, ${col}] · 局部加权和 = ${f(conv(inputImage,k,row,col))} · ${p.kernel??'边缘检测'}`;break}
case 14:{const pos=p.pos??Math.floor(t)%4,kind=p.kind??'Max',row=Math.floor(pos/2)*2,col=pos%2*2,a=Array.from({length:4},(_,i)=>poolImage[row+Math.floor(i/2)][col+i%2]),outMat=Array.from({length:2},(_,r)=>Array.from({length:2},(_,c)=>pool([poolImage[r*2][c*2],poolImage[r*2][c*2+1],poolImage[r*2+1][c*2],poolImage[r*2+1][c*2+1]],kind)));matrix(g,poolImage,35,25,44,{highlight:Array.from({length:4},(_,i)=>[row+Math.floor(i/2),col+i%2])});text(g,'→',264,120,C.cyan,30);matrix(g,outMat,330,65,49,{accent:C.cyan,highlight:[[Math.floor(pos/2),pos%2]]});text(g,kind==='Max'?'MAX POOL':'AVG POOL',370,215,C.cyan,18);out=`区域 [${a.join(', ')}]  →  ${kind==='Max'?'最大值':'平均值'} = ${f(pool(a,kind))}`;break}
case 15:{const shift=p.shift??5,scale=p.scale??1,a=[-2,-1,0,1,2].map(v=>v*scale+shift),z=normalize(a);[a,z].forEach((arr,i)=>{const left=30+i*260;line(g,left,150,left+200,150,C.grid);arr.forEach((v,j)=>{const h=Math.max(-65,Math.min(100,v*(i?40:9)));box(g,left+10+j*35,Math.min(150,150-h),22,Math.abs(h)||1,i?C.purple:C.pink,(i?C.purple:C.pink)+'88')});text(g,i?'标准化后':'原始数据',left+98,222,i?C.purple:C.pink)});out=`原均值 ${f(mean(a))} → 新均值 ${f(mean(z))} · 新数据 [${z.map(f).join(', ')}]`;break}
case 16:{const words=['猫','狗','苹果','梨'],points=[[115,75],[165,105],[340,155],[382,128]],q=words.indexOf(p.word??'猫');axes(g);points.forEach((pt,i)=>{if(i!==q)line(g,...points[q],...pt,C.grid,1);dot(g,...pt,i===q?10:6,i<2?C.pink:C.lime,i===q);text(g,words[i],pt[0],pt[1]-18,i<2?C.pink:C.lime,18)});out=`${words[q]} → [${points[q].map(v=>(v/100).toFixed(2)).join(', ')}] · 教学示意坐标`;break}
case 17:{const q=['猫','喜欢','鱼'].indexOf(p.query??'猫'),Q=[[1,0],[.2,1],[.8,.5]],K=[[1,.1],[.2,1],[.9,.2]],V=[[1,0],[0,1],[.8,.4]],scores=K.map(k=>(Q[q][0]*k[0]+Q[q][1]*k[1])/Math.sqrt(2)*(p.sharp??1)),a=softmax(scores),v=[0,1].map(j=>a.reduce((s,w,i)=>s+w*V[i][j],0));['猫','喜欢','鱼'].forEach((word,i)=>{line(g,250,57,95+i*155,167,C.pink+Math.round((.12+a[i]*.88)*255).toString(16).padStart(2,'0'),2+a[i]*10);dot(g,95+i*155,167,13,C.pink);text(g,word,95+i*155,210,C.pink,20);text(g,`${(a[i]*100).toFixed(0)}%`,95+i*155,139,C.lime,19)});ring(g,250,57,24,C.lime);text(g,['猫','喜欢','鱼'][q],250,64,C.lime,19);out=`注意力 [${a.map(f).join(', ')}] · 加权输出 [${v.map(f).join(', ')}]`;break}
case 18:{const pDrop=p.p??.4,mode=p.mode??'训练',seed=state.seed??1,mask=Array.from({length:12},(_,i)=>((Math.sin((i+1)*127.1+seed*311.7)*43758.5453)%1+1)%1>=pDrop),active=mode==='推理'?12:mask.filter(Boolean).length;for(let i=0;i<12;i++){const on=mode==='推理'||mask[i],x=80+i%6*67,y=75+Math.floor(i/6)*88;ring(g,x,y,16,on?C.lime:C.grid);if(on)dot(g,x,y,6,C.lime,true);else{line(g,x-6,y-6,x+6,y+6,'#576252');line(g,x+6,y-6,x-6,y+6,'#576252')}}out=`${mode}模式 · 本次保留 ${active}/12 个激活 · 保留值缩放 ${mode==='推理'?'1.00':f(1/(1-pDrop))} 倍`;break}
case 19:{const x=p.x??1,a=p.a??.2,on=p.skip!=='关闭',y=a*x+(on?x:0);signal(g,[55,140],[250,140],t*.5,C.pink);signal(g,[250,140],[435,140],t*.5-.3,C.pink);if(on){path(g,[[55,140],[55,45],[435,45],[435,140]],C.lime,2);dot(g,55+380*((t*.25)%1),45,4,C.lime,true);text(g,'identity / x',245,32,C.lime,16)}box(g,185,106,130,66,C.pink);text(g,'F(x) = ax',250,147,C.pink,20);ring(g,435,140,21,C.lime);text(g,'+',435,147,C.lime,24);text(g,`x=${f(x)}`,55,208,C.muted);text(g,`y=${f(y)}`,423,208,C.lime);out=`F(x) = ${f(a*x)} ${on?`· 旁路 x = ${f(x)}`:''}  →  y = ${f(y)}`;break}
case 20:{const s=state.training??{w:-.5,b:0,step:0,loss:0,history:[]};axes(g,35,205,250,175);trainData.forEach(([x,y])=>dot(g,40+x*225,205-y/3.5*170,4,C.cyan));line(g,40,205-s.b/3.5*170,265,205-(s.w+s.b)/3.5*170,C.lime,3);text(g,'数据与拟合',155,27,C.muted,16);line(g,320,205,470,205,C.grid);line(g,320,205,320,48,C.grid);const hist=s.history;if(hist.length>1)path(g,hist.map((v,i)=>[320+i/(hist.length-1)*150,205-Math.min(7,v)/7*150]),C.orange,2);text(g,'实际 MSE',390,27,C.orange,16);text(g,`step ${s.step}`,395,232,C.muted,16);out=`更新 ${s.step} 次 · w=${f(s.w)} · b=${f(s.b)} · MSE=${s.loss.toFixed(4)}`;break}
}return out}
